    "css": ".card {\n  width: 260px;\n  background-color: #fff;\n  border: 1px solid #ccc;\n  border-radius: 5px;\n  box-shadow: 2px 2px 5px rgba(0, 0, 0, 0.1);\n}\n\n.chat-header {\n  background-color: #333;\n  color: #fff;\n  padding: 10px;\n  font-size: 18px;\n  border-top-left-radius: 5px;\n  border-top-right-radius: 5px;\n}\n\n.chat-window {\n  height: 220px;\n  overflow-y: scroll;\n}\n\n.message-list {\n  list-style: none;\n  margin: 0;\n  padding: 0;\n}\n\n.chat-input {\n  display: flex;\n  align-items: center;\n  padding: 10px;\n  border-top: 1px solid #ccc;\n}\n\n.message-input {\n  flex: 1;\n  border: none;\n  outline: none;\n  padding: 5px;\n  font-size: 14px;\n}\n\n.send-button {\n  border: none;\n  outline: none;\n  background-color: #333;\n  color: #fff;\n  font-size: 14px;\n  padding: 5px 10px;\n  cursor: pointer;\n}\n\n.send-button:hover {\n  background-color: rgb(255, 255, 255);\n  color: rgb(0, 0, 0);\n  box-shadow: 0 4px 18px 0 rgba(0, 0, 0, 0.25);\n}"
