    "css": ".form-container {\n  width: 400px;\n  background: linear-gradient(#212121, #212121) padding-box,\n              linear-gradient(145deg, transparent 35%,#e81cff, #40c9ff) border-box;\n  border: 2px solid transparent;\n  padding: 32px 24px;\n  font-size: 14px;\n  font-family: inherit;\n  color: white;\n  display: flex;\n  flex-direction: column;\n  gap: 20px;\n  box-sizing: border-box;\n  border-radius: 16px;\n}\n\n.form-container button:active {\n  scale: 0.95;\n}\n\n.form-container .form {\n  display: flex;\n  flex-direction: column;\n  gap: 20px;\n}\n\n.form-container .form-group {\n  display: flex;\n  flex-direction: column;\n  gap: 2px;\n}\n\n.form-container .form-group label {\n  display: block;\n  margin-bottom: 5px;\n  color: #717171;\n  font-weight: 600;\n  font-size: 12px;\n}\n\n.form-container .form-group input {\n  width: 100%;\n  padding: 12px 16px;\n  border-radius: 8px;\n  color: #fff;\n  font-family: inherit;\n  background-color: transparent;\n  border: 1px solid #414141;\n}\n\n.form-container .form-group textarea {\n  width: 100%;\n  padding: 12px 16px;\n  border-radius: 8px;\n  resize: none;\n  color: #fff;\n  height: 96px;\n  border: 1px solid #414141;\n  background-color: transparent;\n  font-family: inherit;\n}\n\n.form-container .form-group input::placeholder {\n  opacity: 0.5;\n}\n\n.form-container .form-group input:focus {\n  outline: none;\n  border-color: #e81cff;\n}\n\n.form-container .form-group textarea:focus {\n  outline: none;\n  border-color: #e81cff;\n}\n\n.form-container .form-submit-btn {\n  display: flex;\n  align-items: flex-start;\n  justify-content: center;\n  align-self: flex-start;\n  font-family: inherit;\n  color: #717171;\n  font-weight: 600;\n  width: 40%;\n  background: #313131;\n  border: 1px solid #414141;\n  padding: 12px 16px;\n  font-size: inherit;\n  gap: 8px;\n  margin-top: 8px;\n  cursor: pointer;\n  border-radius: 6px;\n}\n\n.form-container .form-submit-btn:hover {\n  background-color: #fff;\n  border-color: #fff;\n}\n\n\n\n"
