    "css": ".form {\n  display: flex;\n  flex-direction: column;\n  gap: 10px;\n  padding-left: 2em;\n  padding-right: 2em;\n  padding-bottom: 0.4em;\n  background-color: #171717;\n  border-radius: 25px;\n  transition: .4s ease-in-out;\n}\n\n.form:hover {\n  transform: scale(1.05);\n  border: 1px solid black;\n}\n\n#heading {\n  text-align: center;\n  margin: 2em;\n  color: rgb(255, 255, 255);\n  font-size: 1.2em;\n}\n\n.field {\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  gap: 0.5em;\n  border-radius: 25px;\n  padding: 0.6em;\n  border: none;\n  outline: none;\n  color: white;\n  background-color: #171717;\n  box-shadow: inset 2px 5px 10px rgb(5, 5, 5);\n}\n\n.input-icon {\n  height: 1.3em;\n  width: 1.3em;\n  fill: white;\n}\n\n.input-field {\n  background: none;\n  border: none;\n  outline: none;\n  width: 100%;\n  color: #d3d3d3;\n}\n\n.form .btn {\n  display: flex;\n  justify-content: center;\n  flex-direction: row;\n  margin-top: 2.5em;\n}\n\n.button1 {\n  padding: 0.5em;\n  padding-left: 1.1em;\n  padding-right: 1.1em;\n  border-radius: 5px;\n  margin-right: 0.5em;\n  border: none;\n  outline: none;\n  transition: .4s ease-in-out;\n  background-color: #252525;\n  color: white;\n}\n\n.button1:hover {\n  background-color: black;\n  color: white;\n}\n\n.button2 {\n  padding: 0.5em;\n  padding-left: 2.3em;\n  padding-right: 2.3em;\n  border-radius: 5px;\n  border: none;\n  outline: none;\n  transition: .4s ease-in-out;\n  background-color: #252525;\n  color: white;\n}\n\n.button2:hover {\n  background-color: black;\n  color: white;\n}\n\n.button3 {\n  margin-bottom: 3em;\n  padding: 0.5em;\n  border-radius: 5px;\n  border: none;\n  outline: none;\n  transition: .4s ease-in-out;\n  background-color: #252525;\n  color: white;\n}\n\n.button3:hover {\n  background-color: red;\n  color: white;\n}"
