    "css": ".form {\n  --input-focus: #2d8cf0;\n  --font-color: #323232;\n  --font-color-sub: #666;\n  --bg-color: beige;\n  --main-color: black;\n  padding: 20px;\n  background: lightblue;\n  display: flex;\n  flex-direction: column;\n  align-items: flex-start;\n  justify-content: center;\n  gap: 20px;\n  border-radius: 5px;\n  border: 2px solid var(--main-color);\n  box-shadow: 4px 4px var(--main-color);\n}\n\n.title {\n  color: var(--font-color);\n  font-weight: 900;\n  font-size: 20px;\n  margin-bottom: 25px;\n}\n\n.title span {\n  color: var(--font-color-sub);\n  font-weight: 600;\n  font-size: 17px;\n}\n\n.input {\n  width: 250px;\n  height: 40px;\n  border-radius: 5px;\n  border: 2px solid var(--main-color);\n  background-color: var(--bg-color);\n  box-shadow: 4px 4px var(--main-color);\n  font-size: 15px;\n  font-weight: 600;\n  color: var(--font-color);\n  padding: 5px 10px;\n  outline: none;\n}\n\n.input::placeholder {\n  color: var(--font-color-sub);\n  opacity: 0.8;\n}\n\n.input:focus {\n  border: 2px solid var(--input-focus);\n}\n\n.login-with {\n  display: flex;\n  gap: 20px;\n}\n\n.button-log {\n  cursor: pointer;\n  width: 40px;\n  height: 40px;\n  border-radius: 100%;\n  border: 2px solid var(--main-color);\n  background-color: var(--bg-color);\n  box-shadow: 4px 4px var(--main-color);\n  color: var(--font-color);\n  font-size: 25px;\n  display: flex;\n  justify-content: center;\n  align-items: center;\n}\n\n.icon {\n  width: 24px;\n  height: 24px;\n  fill: var(--main-color);\n}\n\n.button-log:active, .button-confirm:active {\n  box-shadow: 0px 0px var(--main-color);\n  transform: translate(3px, 3px);\n}\n\n.button-confirm {\n  margin: 50px auto 0 auto;\n  width: 120px;\n  height: 40px;\n  border-radius: 5px;\n  border: 2px solid var(--main-color);\n  background-color: var(--bg-color);\n  box-shadow: 4px 4px var(--main-color);\n  font-size: 17px;\n  font-weight: 600;\n  color: var(--font-color);\n  cursor: pointer;\n}\n"
